const getSequenceGaps = `-- name: GetSequenceGaps :many
WITH sequence_range AS (
  SELECT
    generate_series(
      1,
      (
        SELECT
          MAX(es1.sequence)
        FROM
          entitystate es1
        WHERE
          es1.entity_id = $1
          AND es1.key = $2
          AND es1.fiscal_year = $3
          AND es1.tenant_id = current_tenant_id()
      )
    ) AS seq_num
)
SELECT
  seq_num AS missing_sequence
FROM
  sequence_range
WHERE
  seq_num NOT IN (
    SELECT
      es2.sequence
    FROM
      entitystate es2
    WHERE
      es2.entity_id = $1
      AND es2.key = $2
      AND es2.fiscal_year = $3
      AND es2.tenant_id = current_tenant_id()
  )
`

