const validateSequenceIntegrity = `-- name: ValidateSequenceIntegrity :many
SELECT
  entity_id,
  KEY,
  fiscal_year,
  sequence,
  CASE
    WHEN sequence <= 0 THEN 'Invalid: Non-positive sequence'
    WHEN sequence = 1 THEN 'OK: Initial state'
    ELSE 'OK: In use'
  END AS STATUS
FROM
  entitystate
WHERE
  tenant_id = current_tenant_id()
  AND (
    sequence <= 0
    OR sequence IS NULL
  )
ORDER BY
  entity_id,
  KEY,
  fiscal_year
`

